//! AArch64 (A64) decoder generated from Arm's machine-readable specification.
//!
//! `spec.rs` is generated by `tools/armgen` and identifies the encoding of every instruction word, its aliases
//! and its assembly syntax. The operand semantics the open-source specification leaves out (how field values
//! become register names, immediates and labels) are written by hand in `operands.rs`.

mod flow;
mod helpers;
mod operands;
#[allow(clippy::all)]
#[rustfmt::skip]
mod spec;
mod spec_types;
mod undefined;

use crate::mrs::{self, Encoding, State, Syntax};

use crate::{Disassembler, Flow, Insn, JumpTable};

pub use operands::LabelStyle;

pub(crate) fn logical_immediate(word: u32, width: u8) -> Option<u64> {
    helpers::decode_bit_masks(
        u64::from((word >> 22) & 1),
        u64::from((word >> 10) & 63),
        u64::from((word >> 16) & 63),
        true,
        u32::from(width),
    )
}

/// A decoded instruction word: the encoding it matched and the syntax chosen to display it.
#[derive(Clone, Copy)]
pub struct Decoded {
    pub word: u32,
    pub encoding: &'static Encoding,
    pub syntax: &'static Syntax,
}

impl Decoded {
    /// The value of the named encoding field.
    pub fn field(&self, name: &str) -> Option<u64> {
        self.encoding.field(self.word, name)
    }
}

/// How many instructions after a call to the next instruction are searched for a read of the return address.
const LINK_READ_WINDOW: usize = 4;

/// Whether the code in `bytes`, which a `bl` links to, takes the return address in x30 as a value (the get-PC idiom
/// `bl 1f; 1: mov x0, x30`) before anything saves, overwrites or branches: a callee's prologue saves it instead.
fn reads_link(bytes: &[u8]) -> bool {
    const LINK: u64 = 30;
    for chunk in bytes.as_chunks::<4>().0.iter().take(LINK_READ_WINDOW) {
        let Some(decoded) = decode_word(u32::from_le_bytes(*chunk)) else { return false };
        let name = decoded.encoding.name;
        let is = |field: &str| decoded.field(field) == Some(LINK);
        if name.contains("branch") || is("Rd") || is("Rt") || is("Rt2") {
            return false;
        }
        if is("Rn") || is("Rm") {
            return true;
        }
    }
    false
}

/// Finds the encoding of `word`, or `None` when it is unallocated.
pub fn lookup(word: u32) -> Option<&'static Encoding> {
    spec::TABLES.lookup(word, State::default())
}

/// Decodes `word`, choosing the preferred alias for display. Returns `None` for unallocated and UNDEFINED
/// encodings.
pub fn decode_word(word: u32) -> Option<Decoded> {
    let encoding = lookup(word)?;
    let syntax = spec::TABLES.preferred_syntax(encoding, word, State::default());
    let decoded = Decoded { word, encoding, syntax };
    (!undefined::is_undefined(&decoded)).then_some(decoded)
}

/// Renders `word` at `address` as assembly text, or `None` when it is unallocated.
pub fn format_word(word: u32, address: u64, labels: LabelStyle) -> Option<String> {
    let decoded = decode_word(word)?;
    mrs::render_with_fallback(decoded.syntax, &decoded.encoding.syntax, &|syntax, operand| {
        let decoded = Decoded { syntax, ..decoded };
        operands::render(&operands::Context { decoded: &decoded, address, labels }, operand)
    })
}

#[derive(Default)]
pub struct A64Disassembler {
    addresses: flow::Addresses,
    resolved: Option<Flow>,
    jump_base: Option<u64>,
    jump_table: Option<JumpTable>,
}

impl Disassembler for A64Disassembler {
    fn reset(&mut self) {
        let memory_changed = self.addresses.memory_changed;
        self.addresses = flow::Addresses::default();
        self.addresses.memory_changed = memory_changed;
        self.resolved = None;
        self.jump_base = None;
        self.jump_table = None;
    }

    fn begin_run(&mut self) {
        self.addresses = flow::Addresses::default();
        self.resolved = None;
        self.jump_base = None;
        self.jump_table = None;
    }

    fn decode(&mut self, bytes: &[u8], address: u64) -> Insn {
        self.decode_with_memory(bytes, address, &|_, _| None)
    }

    fn decode_with_memory(&mut self, bytes: &[u8], address: u64, read: &dyn Fn(u64, u8) -> Option<u64>) -> Insn {
        self.resolved = None;
        self.jump_base = None;
        self.jump_table = None;
        let Some(word) = bytes.first_chunk::<4>().map(|chunk| u32::from_le_bytes(*chunk)) else {
            return Insn {
                address,
                len: bytes.len().clamp(1, 4) as u8,
                flow: Flow::Invalid,
                data_ref: None,
                accesses: false,
                immediate: None,
                conditional: false,
            };
        };
        match decode_word(word) {
            Some(decoded) => {
                let flow::Analysis { mut flow, data_ref, accesses, immediate, jump_base, jump_table } =
                    flow::analyze(&decoded, address, &mut self.addresses, read);
                if flow == Flow::Call(address.wrapping_add(4)) && reads_link(&bytes[4..]) {
                    flow = Flow::Next;
                }
                self.jump_table = jump_table;
                if matches!(decoded.encoding.name, "BR_64_branch_reg" | "BLR_64_branch_reg") {
                    self.resolved = Some(flow);
                }
                self.jump_base = jump_base;
                Insn { address, len: 4, flow, data_ref, accesses, immediate, conditional: false }
            }
            None => Insn {
                address,
                len: 4,
                flow: Flow::Invalid,
                data_ref: None,
                accesses: false,
                immediate: None,
                conditional: false,
            },
        }
    }

    fn format(&mut self, bytes: &[u8], address: u64) -> String {
        bytes
            .first_chunk::<4>()
            .and_then(|chunk| format_word(u32::from_le_bytes(*chunk), address, LabelStyle::Absolute))
            .unwrap_or_else(|| "(bad)".to_owned())
    }

    fn resolved_flow(&self) -> Option<Flow> {
        self.resolved
    }

    fn indirect_jump_base(&self) -> Option<u64> {
        self.jump_base
    }

    fn jump_table(&self) -> Option<JumpTable> {
        self.jump_table
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn lookup_linear(word: u32) -> Option<&'static Encoding> {
        spec::TABLES.lookup_linear(word, State::default())
    }

    #[test]
    fn decision_tree_agrees_with_a_linear_scan() {
        let mut state = 7u64;
        for _ in 0..20_000 {
            state = state.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
            let word = (state >> 32) as u32;
            let tree = lookup(word).map(|encoding| encoding.name);
            let linear = lookup_linear(word).map(|encoding| encoding.name);
            assert_eq!(tree, linear, "word {word:#010x}");
        }
        // Every encoding's own pattern reaches it (or a narrower encoding carved out of it).
        for encoding in &spec::ENCODINGS {
            let found = lookup(encoding.value).map(|found| found.name);
            assert_eq!(found, lookup_linear(encoding.value).map(|found| found.name), "{}", encoding.name);
        }
    }

    #[test]
    fn every_encoding_formats_without_panicking() {
        // Random words rarely land on a given encoding, so fill each encoding's free bits instead. Debug builds
        // trap arithmetic overflow in the operand code.
        let mut state = 11u64;
        for encoding in &spec::ENCODINGS {
            for _ in 0..64 {
                state = state.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407);
                let word = ((state >> 32) as u32 & !encoding.mask) | encoding.value;
                let _ = format_word(word, 0x1000, LabelStyle::Absolute);
            }
        }
    }

    fn decode(disassembler: &mut A64Disassembler, word: u32, address: u64) -> Insn {
        disassembler.decode(&word.to_le_bytes(), address)
    }

    #[test]
    fn branches_have_targets_and_kinds() {
        let mut d = A64Disassembler::default();
        assert_eq!(decode(&mut d, 0x9400_0004, 0x1000).flow, Flow::Call(0x1010));
        assert_eq!(decode(&mut d, 0x1400_0002, 0x1000).flow, Flow::Jump(0x1008));
        assert_eq!(decode(&mut d, 0x54ff_ff41, 0x1000).flow, Flow::ConditionalJump(0xfe8));
        assert_eq!(decode(&mut d, 0xb400_0080, 0x1000).flow, Flow::ConditionalJump(0x1010));
        assert_eq!(decode(&mut d, 0x36f8_00a8, 0x1000).flow, Flow::ConditionalJump(0x1014));
        assert_eq!(decode(&mut d, 0xd65f_03c0, 0x1000).flow, Flow::Return);
        assert_eq!(decode(&mut d, 0xd61f_0200, 0x1000).flow, Flow::IndirectJump);
        assert_eq!(decode(&mut d, 0xd63f_0100, 0x1000).flow, Flow::IndirectCall);
        assert_eq!(decode(&mut d, 0xd420_0020, 0x1000).flow, Flow::Halt); // brk #1
        // bl 0x1004 reads the PC when the code there takes x30 as a value, and calls a following function that
        // saves it (stp x29, x30, [sp, #-16]!).
        let call = |next: u32| {
            let bytes: Vec<u8> = [0x9400_0001, next].iter().flat_map(|word: &u32| word.to_le_bytes()).collect();
            A64Disassembler::default().decode(&bytes, 0x1000).flow
        };
        assert_eq!(call(0xaa1e_03e0), Flow::Next); // mov x0, x30
        assert_eq!(call(0x9100_23c1), Flow::Next); // add x1, x30, #8
        assert_eq!(call(0xa9bf_7bfd), Flow::Call(0x1004)); // stp x29, x30, [sp, #-16]!
        assert_eq!(decode(&mut d, 0x9400_0001, 0x1000).flow, Flow::Call(0x1004));
        assert_eq!(decode(&mut d, 0xd420_7d00, 0x1000).flow, Flow::Halt); // brk #0x3e8
        assert_eq!(decode(&mut d, 0x0000_0000, 0x1000).flow, Flow::Halt); // udf #0
        // A debugger resumes from other breakpoints and from semihosting calls.
        assert_eq!(decode(&mut d, 0xd43e_0000, 0x1000).flow, Flow::Next); // brk #0xf000
        assert_eq!(decode(&mut d, 0xd45e_0000, 0x1000).flow, Flow::Next); // hlt #0xf000
        assert_eq!(decode(&mut d, 0xffff_ffff, 0x1000).flow, Flow::Invalid);
        // b.al always branches.
        assert_eq!(decode(&mut d, 0x5400_004e, 0x1000).flow, Flow::Jump(0x1008));
    }

    #[test]
    fn adrp_pairs_resolve_data_references() {
        let mut d = A64Disassembler::default();
        // adrp x0, 0x100000000; add x0, x0, #1172
        assert_eq!(decode(&mut d, 0x9000_0000, 0x1_0000_0470).data_ref, None);
        assert_eq!(decode(&mut d, 0x9112_5000, 0x1_0000_0474).data_ref, Some(0x1_0000_0494));
        // The ADD replaced x0, so a second ADD through x0 resolves nothing.
        assert_eq!(decode(&mut d, 0x9112_5000, 0x1_0000_0478).data_ref, None);
        // adrp x16, 0x100004000; ldr x16, [x16, #8]
        decode(&mut d, 0x9000_0030, 0x1_0000_0488);
        assert_eq!(decode(&mut d, 0xf940_0610, 0x1_0000_048c).data_ref, Some(0x1_0000_4008));
        // Literal loads reference their target directly: ldr x0, #8
        assert_eq!(decode(&mut d, 0x5800_0040, 0x2000).data_ref, Some(0x2008));
    }

    /// Decodes a straight-line sequence from `address` and returns each instruction's data reference.
    fn data_refs(words: &[u32], address: u64) -> Vec<Option<u64>> {
        let mut d = A64Disassembler::default();
        words.iter().enumerate().map(|(i, &word)| decode(&mut d, word, address + 4 * i as u64).data_ref).collect()
    }

    #[test]
    fn loads_through_a_formed_address_reference_its_fields() {
        // adrp x8, page; add x8, x8, #0x10; ldr x0, [x8, #8]
        assert_eq!(data_refs(&[0x9000_0008, 0x9100_4108, 0xf940_0500], 0x1000), [None, Some(0x1010), Some(0x1018)]);
    }

    #[test]
    fn writes_through_other_fields_forget_addresses() {
        let page = 0x1_0000_0000;
        // ldp x0, x1, [sp] overwrites x1.
        assert_eq!(data_refs(&[0x9000_0001, 0xa940_07e0, 0x9100_2022], page)[2], None);
        // ldr x0, [x16, #8]! moves x16 past the page.
        assert_eq!(data_refs(&[0x9000_0010, 0xf840_8e00, 0x9100_4201], page)[2], None);
        // mrs x0, tpidr_el0 overwrites x0.
        assert_eq!(data_refs(&[0x9000_0000, 0xd53b_d040, 0x9100_2001], page)[2], None);
        // swp x2, x0, [x3] and cas x1, x2, [x3] overwrite x0 and x1.
        assert_eq!(data_refs(&[0x9000_0000, 0xf822_8060, 0x9100_2001], page)[2], None);
        assert_eq!(data_refs(&[0x9000_0001, 0xc8a1_7c62, 0x9100_2022], page)[2], None);
        // bl and svc clobber caller-saved registers.
        assert_eq!(data_refs(&[0x9000_0000, 0x9400_0002, 0x9100_2001], page)[2], None);
        assert_eq!(data_refs(&[0x9000_0000, 0xd400_0001, 0xf940_0401], page)[2], None);
        // SVE incb x8 and lastb x8, p0, z0.d overwrite x8.
        assert_eq!(data_refs(&[0x9000_0008, 0x0430_e3e8, 0xf940_0501], page)[2], None);
        assert_eq!(data_refs(&[0x9000_0008, 0x05e1_a008, 0xf940_0501], page)[2], None);
    }

    #[test]
    fn simd_destinations_leave_general_registers_alone() {
        // adrp x8, page; fadd d8, d8, d2; ldr x1, [x8, #8]
        let page = 0x1_0000_0000;
        assert_eq!(data_refs(&[0x9000_0008, 0x1e62_2908, 0xf940_0501], page)[2], Some(page + 8));
    }

    #[test]
    fn reset_forgets_pages() {
        let mut d = A64Disassembler::default();
        decode(&mut d, 0x9000_0000, 0x1000);
        d.reset();
        assert_eq!(decode(&mut d, 0x9112_5000, 0x1004).data_ref, None);
    }

    #[test]
    fn undefined_encodings_are_rejected() {
        // ubfm w26, w26, #58, #54: 32-bit bitfields take 5-bit positions.
        assert!(decode_word(0x533a_db5a).is_none());
        // caspa x1, x2, ...: register pairs start at even registers.
        assert!(decode_word(0x4861_7ef3).is_none());
        // add v0.1d, v0.1d, v0.1d: the 1D arrangement is reserved for vector ADD.
        assert_eq!(format_word(0x0ee0_8400, 0, LabelStyle::Relative), None);
    }
}
